SELECT percentile_cont(0.75) within GROUP (ORDER BY los) AS high_instability_score_percentile, SUM(CASE WHEN d.icd_code = '304' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(d.icd_code), 0) AS mortality_rate, SUM(CASE WHEN l.itemid IN (SELECT itemid FROM d_labitems WHERE category = 'Critical') THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(l.itemid), 0) AS critical_lab_rate FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id JOIN labevents l ON a.subject_id = l.subject_id WHERE p.gender = 'M' AND p.anchor_age = 54 AND EXTRACT(YEAR FROM a.admittime) >= 2015 AND EXTRACT(YEAR FROM a.dischtime) <= 2016 AND (d.icd_code = '304' OR d.icd_code = '305') AND (l.itemid IN (SELECT itemid FROM d_labitems WHERE category = 'Critical'));